    import { Router } from '@angular/router';

    import { CartService } from '../cart/cart.service';
    import { Delivery, OrdersApi } from '../../core/api/orders.api';

    type DeliveryFormState = Delivery;

    const EMPTY_DELIVERY: DeliveryFormState = {
      name: '', street: '', postalCode: '', city: '', country: '', email: '', phone: '',
    };

    @Component({
      selector: 'app-checkout',
      imports: [],
      templateUrl: './checkout.html',
      styleUrl: './checkout.scss',
    })
    export class Checkout {
      private readonly cartService = inject(CartService);
      private readonly ordersApi = inject(OrdersApi);
      private readonly router = inject(Router);

      protected readonly items = this.cartService.items;
      protected readonly totalAmount = this.cartService.totalAmount;
      protected readonly delivery = signal<DeliveryFormState>(EMPTY_DELIVERY);
      protected readonly submitting = signal(false);
      protected readonly submitError = signal<string | null>(null);

      protected readonly canSubmit = computed(() => this.items().length > 0 && !this.submitting());

      protected updateField(field: keyof DeliveryFormState, value: string): void {
        this.delivery.update((d) => ({ ...d, [field]: value }));
      }

      protected submit(): void {
        if (!this.canSubmit()) {
          return;
        }
        this.submitting.set(true);
        this.submitError.set(null);
        const request = {
          items: this.items().map((i) => ({ productId: i.productId, supplierId: i.supplierId, quantity: i.quantity })),
          delivery: this.delivery(),
        };
        this.ordersApi.createOrder(request).subscribe({
          next: (order) => {
            this.cartService.clear();
            this.router.navigate(['/orders', order.publicId]);
          },
          error: () => {
            this.submitting.set(false);
            this.submitError.set('Die Bestellung konnte nicht abgeschlossen werden. Bitte überprüfen Sie Ihre Angaben.');
          },
        });
      }
    }
    ```
    Kein `FormsModule`/`ngModel` (projektweite Konvention, siehe `product-detail.ts`/`cart.ts`) — Formularwerte laufen über ein einzelnes `delivery`-Signal mit `updateField`, analog zum Muster in `property-filter.ts`. `canSubmit` blockt Submit bei leerem Warenkorb (defensiv — die Checkout-Seite sollte reell nur mit gefülltem Warenkorb erreicht werden) und während eines laufenden Requests (verhindert Doppel-Submit). Warenkorb wird **erst nach** erfolgreicher Antwort geleert (`next`-Callback, AC #4/AD-4) — bei einem Fehler bleibt der Warenkorb-Frontend-State vollständig erhalten.
  - [ ] `checkout.html`:
    ```html
    @if (items().length === 0) {
      <p class="checkout__empty">Ihr Warenkorb ist leer. Es kann keine Bestellung abgeschlossen werden.</p>
    } @else {
      <form class="checkout" (submit)="$event.preventDefault(); submit()">
        <h1>Bestellung abschließen</h1>
        <label>
          Name
          <input [value]="delivery().name" (input)="updateField('name', $any($event.target).value)" required />
        </label>
        <label>
          Straße
          <input [value]="delivery().street" (input)="updateField('street', $any($event.target).value)" required />
        </label>
        <label>
          PLZ
          <input [value]="delivery().postalCode" (input)="updateField('postalCode', $any($event.target).value)" required />
        </label>
        <label>
          Ort
          <input [value]="delivery().city" (input)="updateField('city', $any($event.target).value)" required />
        </label>
        <label>
          Land
          <input [value]="delivery().country" (input)="updateField('country', $any($event.target).value)" required />
        </label>
        <label>
          E-Mail
          <input type="email" [value]="delivery().email" (input)="updateField('email', $any($event.target).value)" required />
        </label>
        <label>
          Telefon (optional)
          <input [value]="delivery().phone" (input)="updateField('phone', $any($event.target).value)" />
        </label>
        <p class="checkout__total">Gesamtsumme: {{ totalAmount() }} €</p>
        <button type="submit" [disabled]="!canSubmit()">Kaufen</button>
