          next: (order) => {
            this.cartService.clear();
            this.router.navigate(['/orders', order.publicId]);
          },
          error: () => {
            this.submitting.set(false);
            this.submitError.set('Die Bestellung konnte nicht abgeschlossen werden. Bitte überprüfen Sie Ihre Angaben.');
          },
        });
      }
    }
